import numpy as np

arr = np.array(input_grid)
rows, cols = arr.shape

def find_connected_components(grid):
    """Find connected components of non-zero values"""
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and (r, c) not in visited:
                # BFS to find component
                queue = [(r, c)]
                component = set()

                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.add((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr, nc] != 0 and (nr, nc) not in visited:
                                queue.append((nr, nc))

                components.append(component)

    return components

def get_bbox(component):
    """Get bounding box for a component"""
    min_r = min(r for r, _ in component)
    max_r = max(r for r, _ in component)
    min_c = min(c for _, c in component)
    max_c = max(c for _, c in component)
    return (min_r, max_r, min_c, max_c)

def is_rectangle_frame(grid, bbox, component):
    """Check if component forms a rectangular frame"""
    min_r, max_r, min_c, max_c = bbox

    # Check if all four corners are present
    corners = {(min_r, min_c), (min_r, max_c), (max_r, min_c), (max_r, max_c)}
    has_corners = len(component & corners) == 4

    # Check if border cells are present
    top_edge = {(r, c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1) if (r, c) == (min_r, c)}
    bottom_edge = {(r, c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1) if (r, c) == (max_r, c)}
    left_edge = {(r, c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1) if (r, c) == (r, min_c)}
    right_edge = {(r, c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1) if (r, c) == (r, max_c)}

    border_cells = top_edge | bottom_edge | left_edge | right_edge

    # Check how many border cells are actually present
    present_border = len(component & border_cells)
    total_border = len(border_cells)

    return {
        'has_all_corners': has_corners,
        'present_border_fraction': present_border / total_border,
        'component_points': len(component),
        'border_cells': border_cells
    }

components = find_connected_components(arr)
print("Component analysis:")
for i, comp in enumerate(components):
